class BookSerializer(serializers.ModelSerializer):
    class Meta:
        model = Book
        fields = ["id", "title", "isbn", "price", "published_at"]

    def validate_title(self, value):
        if len(value.strip()) < 3:
            raise serializers.ValidationError("عنوان باید حداقل ۳ کاراکتر باشد.")
        return value.strip()

    def validate_isbn(self, value):
        # ISBN باید ۱۰ یا ۱۳ رقم عددی باشد
        clean = value.replace("-", "").strip()
        if not clean.isdigit() or len(clean) not in (10, 13):
            raise serializers.ValidationError("ISBN باید ۱۰ یا ۱۳ رقم عددی باشد.")
        return clean

    def validate_price(self, value):
        if value <= 0:
            raise serializers.ValidationError("قیمت باید بزرگ‌تر از صفر باشد.")
        if value > 1000000:
            raise serializers.ValidationError("قیمت نمی‌تواند بیشتر از یک میلیون باشد.")
        return value

    def validate_published_at(self, value):
        from datetime import date
        if value > date.today():
            raise serializers.ValidationError("تاریخ انتشار نمی‌تواند در آینده باشد.")
        return value

class EventSerializer(serializers.ModelSerializer):
    class Meta:
        model = Event
        fields = ["id", "title", "starts_at", "ends_at", "capacity", "registration_open"]

    def validate(self, attrs):
        # قاعده ۱: پایان باید بعد از شروع باشد
        if attrs["ends_at"] <= attrs["starts_at"]:
            raise serializers.ValidationError(
                {"ends_at": "زمان پایان باید بعد از زمان شروع باشد."}
            )

        # قاعده ۲: اگر ثبت‌نام باز است، باید ظرفیت داشته باشد
        if attrs.get("registration_open") and attrs.get("capacity", 0) <= 0:
            raise serializers.ValidationError(
                {"capacity": "برای ثبت‌نام باز، ظرفیت باید بزرگ‌تر از صفر باشد."}
            )

        return attrs

