@deconstructible
class MaxFileSizeValidator:
    def __init__(self, max_mb):
        self.max_mb = max_mb

    def __call__(self, value):
        if value.size > self.max_mb * 1024 * 1024:
            raise serializers.ValidationError(
                f"حجم فایل نمی‌تواند بیشتر از {self.max_mb} مگابایت باشد."
            )


