from datetime import date
from rest_framework import serializers
from .models import Reservation


class ReservationSerializer(serializers.ModelSerializer):
    class Meta:
        model = Reservation
        fields = ["id", "start_date", "end_date", "guests", "room"]

    def validate_start_date(self, value):
        if value < date.today():
            raise serializers.ValidationError("تاریخ شروع نمی‌تواند در گذشته باشد.")
        return value

    def validate_guests(self, value):
        if value < 1:
            raise serializers.ValidationError("تعداد مهمان باید حداقل ۱ باشد.")
        return value

    def validate(self, attrs):
        if attrs["end_date"] <= attrs["start_date"]:
            raise serializers.ValidationError(
                {"end_date": "تاریخ پایان باید بعد از تاریخ شروع باشد."}
            )
        room = attrs.get("room")
        if room and attrs["guests"] > room.capacity:
            raise serializers.ValidationError(
                {"guests": f"ظرفیت این اتاق {room.capacity} نفر است."}
            )
        return attrs
